<section class="stat-panel wide"><header><div><p class="eyebrow">LANGUAGE</p><h2>Most-used words</h2></div><span>Common filler words removed</span></header>@php($wordMax=max(1,(int)$words->max('total')))<div class="word-cloud">@foreach($words as $word)<span style="font-size:{{ 12+($word->total/$wordMax)*22 }}px" title="{{ number_format($word->total) }} uses">{{ $word->label }}</span>@endforeach</div></section>
