<section class="stat-panel"><header><div><p class="eyebrow">REDDIT</p><h2>Favorite communities</h2></div></header>@php($communityMax=max(1,(int)$communities->max('total')))<div class="rank-list">@forelse($communities as $item)<div><b>r/{{ $item->label }}</b><i><span style="width:{{ ($item->total/$communityMax)*100 }}%"></span></i><small>{{ number_format($item->total) }}</small></div>@empty<p>No Reddit communities found.</p>@endforelse</div></section>
<section class="stat-panel wide"><header><div><p class="eyebrow">PHOTOGRAPHY</p><h2>Photos per year</h2></div></header>@php($photoMax=max(1,(int)$photosByYear->max('total')))<div class="photo-history">@foreach($photosByYear as $item)<div><i style="height:{{ ($item->total/$photoMax)*100 }}%" title="{{ $item->label }} · {{ number_format($item->total) }} photos"></i><span>{{ $item->label }}</span></div>@endforeach</div></section>
<section class="stat-panel full"><header><div><p class="eyebrow">PLATFORMS</p><h2>Services used over time</h2></div></header>@php($serviceGroups=$serviceYears->groupBy('year'))<div class="service-history">@foreach($serviceGroups as $year=>$items)@php($total=$items->sum('total'))<div><b>{{ $year }}</b><i>@foreach($items as $item)<span data-service="{{ $item->platform }}" style="width:{{ ($item->total/$total)*100 }}%" title="{{ ucfirst($item->platform) }} · {{ number_format($item->total) }}"></span>@endforeach</i><small>{{ number_format($total) }}</small></div>@endforeach</div><div class="service-legend">@foreach($serviceYears->pluck('platform')->unique() as $service)<span data-service="{{ $service }}"><i></i>{{ ucfirst($service) }}</span>@endforeach</div></section>
